mapper.select:
SELECT cs.id, cs.student_id AS studentId, su.realname AS studentName, cs.teaching_id AS teachingId, cs.course_id AS courseId, c.course_name AS courseName, c.course_code AS courseCode, ( SELECT GROUP_CONCAT(u2.realname ORDER BY u2.realname SEPARATOR '、') FROM sys_user u2 WHERE FIND_IN_SET(u2.id, t.teacher_id) ) AS teacherName, cs.depart_id AS departId, d.depart_name AS departName, cs.semester, cs.academic_year AS academicYear, cs.status, cs.selected_at AS selectedAt FROM ( SELECT * FROM ainote_course_selection
${ew.customSqlSegment}
) cs LEFT JOIN sys_user su ON cs.student_id = su.id LEFT JOIN ainote_teaching t ON cs.teaching_id = t.id LEFT JOIN ainote_course c ON cs.course_id = c.id LEFT JOIN sys_depart d ON cs.depart_id = d.id

SELECT t.id AS teachingId, c.course_name AS courseName, c.course_code AS courseCode, ( SELECT GROUP_CONCAT(u2.realname ORDER BY u2.realname SEPARATOR '、') FROM sys_user u2 WHERE FIND_IN_SET(u2.id, t.teacher_id) ) AS teacherName, d.depart_name AS departName, t.semester AS semester, COUNT(cs.id) AS studentCount FROM ainote_teaching t INNER JOIN ainote_course c ON t.course_id = c.id LEFT JOIN sys_depart d ON t.depart_id = d.id LEFT JOIN ainote_course_selection cs ON cs.teaching_id = t.id AND cs.status = 1 AND cs.tenant_id = #{tenantId} WHERE t.tenant_id = #{tenantId}
AND FIND_IN_SET(#{teacherFilter}, t.teacher_id)
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND t.semester = #{semester}
GROUP BY t.id, c.course_name, c.course_code, d.depart_name, t.semester ORDER BY t.semester DESC, c.course_name ASC

SELECT DISTINCT c.*
FROM ainote_course c

WHERE c.tenant_id = #{tenantId}


INNER JOIN ainote_course_selection cs
       ON cs.course_id = c.id
      AND cs.student_id = #{studentId}
      AND cs.tenant_id  = #{tenantId}
      AND cs.status = 1

ORDER BY c.course_name ASC
